   <div className="columnManagerTop"><div className="columnSearch"><Search size={15}/><input autoFocus placeholder="Search columns..." value={search} onChange={e=>setSearch(e.target.value)}/></div><span>{chosen.length} selected of {cols.length}</span></div>
