function CalculatedDialog({cols,source,steps,initialColumns,initialStep,mode='create',onClose,onApply}:any){
 const[name,setName]=useState(initialStep?.name||'Calculated Column');const[expression,setExpression]=useState(initialStep?.expression||'');const[search,setSearch]=useState('');
 const[prompt,setPrompt]=useState(initialStep?.aiPrompt||'');const[promptCursor,setPromptCursor]=useState(0);const[promptFocus,setPromptFocus]=useState(false);
 const[validation,setValidation]=useState<any>(null);const[aiResult,setAiResult]=useState<any>(null);const[busy,setBusy]=useState(false);const[availableCols,setAvailableCols]=useState<string[]>(cols||[]);
 const editorRef=useRef<HTMLTextAreaElement|null>(null);const promptRef=useRef<HTMLTextAreaElement|null>(null);
 useEffect(()=>{api<any>('/transform/preview',{method:'POST',body:JSON.stringify({source,steps,limit:1})}).then(r=>setAvailableCols(r.columns||Object.keys(r.rows?.[0]||{}))).catch(()=>{})},[source,JSON.stringify(steps)]);
 const filtered=availableCols.filter((c:string)=>c.toLowerCase().includes(search.toLowerCase()));
 const token=currentToken(prompt,promptCursor).toLowerCase();const suggestions=promptFocus&&token?availableCols.filter((c:string)=>c.toLowerCase().includes(token)).slice(0,8):[];
 useEffect(()=>{if(!expression&&initialColumns?.length){setExpression(initialColumns.map((c:string)=>`[${c}]`).join(' + '))}},[]);
 const insert=(text:string)=>{const el=editorRef.current;const pos=el?.selectionStart??expression.length;const next=expression.slice(0,pos)+text+expression.slice(pos);setExpression(next);requestAnimationFrame(()=>{if(editorRef.current){const p=pos+text.length;editorRef.current.focus();editorRef.current.setSelectionRange(p,p)}})};
 const insertPrompt=(c:string)=>{const pos=promptRef.current?.selectionStart??promptCursor;const tok=currentToken(prompt,pos);const start=pos-tok.length;const next=prompt.slice(0,start)+c+prompt.slice(pos);setPrompt(next);setPromptFocus(false);requestAnimationFrame(()=>{const p=start+c.length;promptRef.current?.focus();promptRef.current?.setSelectionRange(p,p)})};
 const validate=async()=>{setBusy(true);try{const r=await api<any>('/transform/calculated-column/validate',{method:'POST',body:JSON.stringify({source,steps,name,expression})});setValidation(r)}catch(e:any){setValidation({valid:false,error:e.message})}finally{setBusy(false)}};
 const generate=async()=>{setBusy(true);try{const r=await api<any>('/transform/calculated-column/ai-generate',{method:'POST',body:JSON.stringify({source,steps,prompt})});setAiResult(r);setName(r.name);setExpression(r.expression);setValidation({valid:true,rows:r.preview,sql:r.compiledSql})}catch(e:any){setAiResult({error:e.message});setValidation(null)}finally{setBusy(false)}};
 const funcs=['IF','CASE WHEN','COALESCE','NULLIF','UPPER','LOWER','TRIM','CONCAT_WS','REPLACE','LENGTH','ROUND','ABS','YEAR','MONTH','QUARTER','WEEK','DAY','DATE_DIFF','DATE_TRUNC','LAST_DAY','CAST'];
 return <Modal title={mode==='edit'?`Edit Calculated Column — ${initialStep?.name||name}`:"Calculated Column — Row Logic + AI"} onClose={onClose} wide><div className="calculatedProLayout">
   <aside className="calcColumnBrowser"><div className="calcPaneTitle"><Columns3 size={15}/><b>Columns</b></div><div className="columnSearch"><Search size={14}/><input placeholder="Search columns" value={search} onChange={e=>setSearch(e.target.value)}/></div><p>Click a field to insert its exact row reference.</p><div className="calcColumnList">{filtered.map((c:string)=><button key={c} onClick={()=>insert(`[${c}]`)}><span>ƒx</span><b>{c}</b><small>[{c}]</small></button>)}</div></aside>
   <section className="calcFormulaPane"><label className="formField"><span>{mode==='edit'?'Calculated column name':'New column name'}</span><input value={name} onChange={e=>setName(e.target.value)}/></label>{mode==='edit'&&<div className="editingObjectBanner"><Pencil size={14}/><span>Editing existing ETL calculated column. Saving updates this Applied Step in place.</span></div>}<div className="calcEditorHead"><div><Braces size={15}/><b>Row expression</b></div><button onClick={validate} disabled={busy||!expression.trim()}><Check size={14}/>{busy?'Checking…':'Validate & Preview'}</button></div><textarea ref={editorRef} className="calcExpressionEditor" value={expression} onChange={e=>{setExpression(e.target.value);setValidation(null)}} spellCheck={false} placeholder={`Examples:\nIF([Status] = 'Done', 'Closed', 'Open')\n[Story Points] * [Days Open]\nCOALESCE([Days Open], 0)`}/><div className="calcFunctionChips">{funcs.map(f=><button key={f} onClick={()=>insert(f==='CASE WHEN'?`CASE WHEN  THEN  ELSE  END`:`${f}()`)}>{f}</button>)}</div><div className="calcHelp"><b>Row-level only:</b> arithmetic, IF/CASE, comparisons, text functions, null handling and date logic. The step runs during ETL and is materialized before Model.</div>{validation&&<div className={'calcValidation '+(validation.valid?'ok':'bad')}>{validation.valid?<><Check size={15}/><div><b>Expression is valid</b><span>Preview of the new column:</span>{validation.rows&&<MiniTable rows={validation.rows} limit={5}/>}</div></>:<><Info size={15}/><div><b>Validation failed</b><span>{validation.error}</span></div></>}</div>}</section>
   <aside className="calcAiPane"><div className="calcAiTitle"><Sparkles size={17}/><div><small>AI ROW LOGIC BUILDER</small><b>Describe the calculated column</b></div></div><div className="calcPromptWrap"><textarea ref={promptRef} value={prompt} onFocus={e=>{setPromptFocus(true);setPromptCursor(e.currentTarget.selectionStart)}} onBlur={()=>setTimeout(()=>setPromptFocus(false),140)} onSelect={e=>setPromptCursor((e.target as HTMLTextAreaElement).selectionStart)} onChange={e=>{setPrompt(e.target.value);setPromptCursor(e.target.selectionStart);setPromptFocus(true)}} placeholder="Examples: If Status is Done then Closed else Open; days between Created and Updated; replace null Days Open with 0..."/>{!!suggestions.length&&<div className="calcPromptSuggestions">{suggestions.map((c:string)=><button key={c} onMouseDown={e=>{e.preventDefault();insertPrompt(c)}}><b>{c}</b><small>Current ETL column</small></button>)}</div>}</div><button className="calcGenerateBtn" onClick={generate} disabled={busy||!prompt.trim()}><Sparkles size={15}/>{busy?'Generating…':'Generate Row Formula'}</button><div className="calcAiGrounding"><b>Grounded to current transformation</b><span>{availableCols.length} available columns</span></div>{aiResult&&!aiResult.error&&<div className="calcAiResult"><b>{aiResult.name}</b><p>{aiResult.explanation}</p><code>{aiResult.expression}</code>{aiResult.warning&&<span className="calcWarning">{aiResult.warning}</span>}</div>}{aiResult?.error&&<div className="calcValidation bad"><Info size={14}/><span>{aiResult.error}</span></div>}</aside>
 </div><div className="dialogActions calculatedActions"><button onClick={onClose}>Cancel</button><button onClick={validate} disabled={!expression.trim()}>Validate</button><button className="primary" disabled={!name.trim()||!expression.trim()||validation?.valid===false} onClick={()=>onApply({type:'calculated_column',label:`Calculated column ${name}`,name,expression,aiPrompt:prompt})}>{mode==='edit'?<><Save size={14}/>Save Changes</>:'Add Calculated Column'}</button></div></Modal>
}

function JoinDialog({source,steps,cols,meta,onClose,onApply}:any){const[other,setOther]=useState(meta.find((m:any)=>m.name!==source)?.name||'');const[rightCols,setRightCols]=useState<string[]>([]);const[keys,setKeys]=useState<any[]>([]);const[joinType,setJoinType]=useState('left');const[profile,setProfile]=useState<any>(null);const[dragLeft,setDragLeft]=useState('');useEffect(()=>{const m=meta.find((x:any)=>x.name===other);setRightCols((m?.columns||[]).map((x:any)=>x.name));setKeys([]);setProfile(null)},[other]);const drop=(right:string)=>{if(!dragLeft)return;setKeys(k=>[...k.filter(x=>x.leftField!==dragLeft),{leftField:dragLeft,rightField:right}]);setDragLeft('')};const preview=async()=>{if(!keys.length)return;const r=await api<any>('/transform/join-profile',{method:'POST',body:JSON.stringify({source,steps,otherTable:other,keys})});setProfile(r)};return <Modal title="Drag-and-Drop Join Designer" onClose={onClose} wide><div className="joinTop"><label>Join type<select value={joinType} onChange={e=>setJoinType(e.target.value)}>{['left','inner','right','full'].map(x=><option key={x}>{x}</option>)}</select></label><label>Right table<select value={other} onChange={e=>setOther(e.target.value)}>{meta.filter((x:any)=>x.name!==source).map((x:any)=><option key={x.name}>{x.name}</option>)}</select></label></div><p className="dialogHint">Drag a field from the left table and drop it on the matching field in the right table.</p><div className="joinDesigner"><div className="joinTable"><h4>{source}</h4>{cols.map((c:string)=><div draggable onDragStart={()=>setDragLeft(c)} className={'joinField '+(keys.some(k=>k.leftField===c)?'linked':'')} key={c}><GripVertical size={12}/>{c}</div>)}</div><div className="joinLines"><Link2 size={28}/>{keys.map((k:any,i:number)=><div key={i}>{k.leftField} = {k.rightField}<button onClick={()=>setKeys(x=>x.filter((_:any,j:number)=>j!==i))}>×</button></div>)}</div><div className="joinTable"><h4>{other}</h4>{rightCols.map(c=><div onDragOver={e=>e.preventDefault()} onDrop={()=>drop(c)} className={'joinField drop '+(keys.some(k=>k.rightField===c)?'linked':'')} key={c}>{c}</div>)}</div></div><button className="profileBtn" disabled={!keys.length} onClick={preview}>Preview Join Match</button>{profile&&<div className="joinProfile"><div><b>{profile.matchRate}%</b><span>Match rate</span></div><div><b>{profile.matchedLeftRows.toLocaleString()}</b><span>Matched left rows</span></div><div><b>{profile.unmatchedLeftRows.toLocaleString()}</b><span>Unmatched left</span></div><div><b>{profile.unmatchedRightRows.toLocaleString()}</b><span>Unmatched right</span></div></div>}<DialogActions onClose={onClose} disabled={!keys.length} onApply={()=>onApply({type:'join',label:`${joinType.toUpperCase()} JOIN ${other}`,otherTable:other,joinType,keys})}/></Modal>}
function AppendDialog({meta,source,onClose,onApply}:any){const[chosen,setChosen]=useState<string[]>([]);return <Modal title="Append / Union Wizard" onClose={onClose}><p className="dialogHint">Select one or more compatible tables. The engine keeps common columns in the same order.</p><div className="checkList">{meta.filter((x:any)=>x.name!==source).map((x:any)=><label key={x.name}><input type="checkbox" checked={chosen.includes(x.name)} onChange={()=>setChosen(c=>c.includes(x.name)?c.filter(z=>z!==x.name):[...c,x.name])}/><span>{x.name}</span><small>{x.columns?.length||0} columns</small></label>)}</div><DialogActions onClose={onClose} disabled={!chosen.length} onApply={()=>onApply({type:'append',label:`Append ${chosen.join(', ')}`,tables:chosen})}/></Modal>}
function GroupDialog({cols,onClose,onApply}:any){const[groups,setGroups]=useState<string[]>([]);const[aggs,setAggs]=useState<any[]>([{field:cols[0]||'',aggregation:'sum',alias:'Total'}]);const upd=(i:number,k:string,v:string)=>setAggs(a=>a.map((x,j)=>j===i?{...x,[k]:v}:x));return <Modal title="Group By" onClose={onClose} wide><div className="groupBuilder"><div><h4>Group by fields</h4><div className="checkList compact">{cols.map((c:string)=><label key={c}><input type="checkbox" checked={groups.includes(c)} onChange={()=>setGroups(g=>g.includes(c)?g.filter(x=>x!==c):[...g,c])}/>{c}</label>)}</div></div><div><h4>Aggregations</h4>{aggs.map((a,i)=><div className="aggRow" key={i}><select value={a.field} onChange={e=>upd(i,'field',e.target.value)}>{cols.map((c:string)=><option key={c}>{c}</option>)}</select><select value={a.aggregation} onChange={e=>upd(i,'aggregation',e.target.value)}>{['sum','avg','min','max','count','distinctcount'].map(x=><option key={x}>{x}</option>)}</select><input value={a.alias} onChange={e=>upd(i,'alias',e.target.value)}/><button onClick={()=>setAggs(x=>x.filter((_,j)=>j!==i))}>×</button></div>)}<button className="addRule" onClick={()=>setAggs(x=>[...x,{field:cols[0]||'',aggregation:'sum',alias:'Total'}])}>+ Add aggregation</button></div></div><DialogActions onClose={onClose} disabled={!aggs.length} onApply={()=>onApply({type:'group_by',label:`Group by ${groups.join(', ')||'(all rows)'}`,groupFields:groups,aggregations:aggs})}/></Modal>}
function DialogActions({onClose,onApply,disabled=false}:any){return <div className="dialogActions"><button onClick={onClose}>Cancel</button><button className="primary" disabled={disabled} onClick={onApply}>Apply Step</button></div>}
